test("last family decision alone can explain payment; early matching candidates cannot hide later known null or invalid replies", () => {
  for (const family of ["cupid", "hybrid"] as const) {
    const record = family === "cupid" ? cupidMixed() : hybridWolf();
    const last = choose(family);
    last.turn = 2; last.request.context.retry_attempt = 1; last.request.context.retry_max = 2;
    last.outcome = family === "cupid"
      ? { kind: "action", action: { name: "choose_lovers", args: { first_id: 2, second_id: 5 } } }
      : { kind: "action", action: { name: "choose_exemplar", args: { target_id: 4 } } };
    record.decisions.push(last);
    reject(record, family);
    const nullReply = structuredClone(record); nullReply.decisions[1]!.outcome = { kind: "action", action: null };
    reject(nullReply, family);
    const invalid = structuredClone(record);
    invalid.decisions[1]!.outcome = { kind: "action", action: { name: "speak", args: { text: "literal_invalid_family_reply" } } };
    reject(invalid, family);
    const opaque = structuredClone(record); opaque.decisions[1]!.outcome = { kind: "error", code: "decision_failed", name: "Error" };
    expect(() => family === "cupid" ? validateCupidRecord(opaque) : validateHybridRecord(opaque)).not.toThrow();
    opaque.decisions[1]!.outcome = { kind: "pending" };
    expect(() => family === "cupid" ? validateCupidRecord(opaque) : validateHybridRecord(opaque)).not.toThrow();
  }
  // 仅写 remaining 的失败前缀也不能借早先有效榜样绕过最后的空回复。
  const debit = hybridWolf(), cp = failure(debit, 0), last = choose("hybrid");
  cp.players[0]!.privateState.hybrid = { remaining: 0, choice: null }; cp.players[0]!.victory = { affiliations: [] };
  last.turn = 2; last.request.context.retry_attempt = 1; last.request.context.retry_max = 2;
  last.outcome = { kind: "action", action: null }; debit.decisions.push(last);
  reject(debit, "hybrid");
  last.outcome = { kind: "error", code: "decision_failed", name: "Error" };
  expect(() => validateHybridRecord(debit)).not.toThrow();
});
